/*
 * THE COACH READS ONE LEARNER'S CONVERSATION (DBU-07). role:staff is checked by
 * nodegx.security.json. Reading marks the learner's messages read and rings her bell once if it
 * marked any, so the coach's unread counts clear. `emailOn` says whether she gets an email when
 * he replies, so the page can tell him when she will only see it on her next visit.
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const learnerId = String(Inputs.learnerId || '');
    const users = learnerId ? await q('_User', { objectId: { equalTo: learnerId } }) : [];
    const plans = users.length ? await q('Plan', { learner: { equalTo: learnerId } }) : [];
    if (!users.length || !plans.length) { Outputs.refused(); return; }
    const learner = users[0];

    const rows = (await q('Message', { learner: { equalTo: learnerId } }))
      .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
    const steps = await q('Step', { learner: { equalTo: learnerId } });
    const titleOf = (id) => { const s = steps.find((x) => x.objectId === id); return s ? String(s.title || '') : ''; };
    const coaches = [...new Set(rows.map((m) => m.author).filter((a) => a !== learnerId))];
    const people = coaches.length ? await q('_User', { objectId: { containedIn: coaches } }) : [];
    const nameOf = (id) => { const u = people.find((p) => p.objectId === id); return String((u && u.name) || 'Coach').split(' ')[0]; };
    const first = String(learner.name || learner.email || '').split(' ')[0];

    const now = new Date().toISOString();
    const unread = rows.filter((m) => m.author === learnerId && !m.readAt);
    Outputs.messages = rows.map((m) => ({
      id: m.objectId,
      mine: m.author !== learnerId,
      who: m.author === learnerId ? first : (m.author === me ? '' : nameOf(m.author)),
      body: String(m.body || ''),
      at: m.createdAt,
      stepId: m.step || '',
      stepTitle: m.step ? titleOf(m.step) : '',
      attachments: (Array.isArray(m.attachments) ? m.attachments : []).map((a) => ({ file: a.file, fileName: a.name })),
      isNew: m.author === learnerId && !m.readAt
    }));
    const mine = await q('_User', { objectId: { equalTo: me } });
    Outputs.me = { name: (mine[0] && mine[0].name) || '', timezone: (mine[0] && mine[0].timezone) || '' };
    Outputs.learner = { id: learnerId, name: learner.name || learner.email || '', first };
    Outputs.emailOn = !learner.emailOptOutAt;
    for (const m of unread) await R.save(m.objectId, { readAt: now }, { className: 'Message' });
    if (unread.length) {
      await R.create('Doorbell', { learner: learnerId, topic: 'message' }, { acl: { [learnerId]: { read: true }, 'role:staff': { read: true } } });
    }
    Outputs.done();
  } catch (e) {
    console.error('[dbu:messagesAsCoach]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
